// view/route-point-view.js
import AbstractView from '../framework/view/abstract-view.js';
import { convertDate, getDestinationById, getDuration, getOffersByType } from '../utils.js';
import { Formats } from '../consts.js';

function createRoutePointTemplate(point, destinations, offers) {
  const { basePrice, dateFrom, dateTo, destination, isFavorite, type } = point;

  const dayValue = convertDate(dateFrom, Formats.TIME_TAG_VALUE);
  const day = convertDate(dateFrom, Formats.DAY);
  const timeStart = convertDate(dateFrom, Formats.TIME);
  const timeEnd = convertDate(dateTo, Formats.TIME);

  const destinationById = getDestinationById(destination, destinations) || { name: 'Unknown' };
  const duration = getDuration(dateFrom, dateTo);

  const selectedOffers = getOffersByType(point, offers)
    .filter((offer) => point.offers.includes(offer.id))
    .map((offer) => `
      <li class="event__offer">
        <span class="event__offer-title">${offer.title}</span>
        +€
        <span class="event__offer-price">${offer.price}</span>
      </li>
    `)
    .join('');

  const favorite = isFavorite ? 'event__favorite-btn--active' : '';

  return `<li class="trip-events__item">
            <div class="event">
              <time class="event__date" datetime="${dayValue}">${day}</time>
              <div class="event__type">
                <img class="event__type-icon" width="42" height="42" src="img/icons/${type}.png" alt="Event type icon">
              </div>
              <h3 class="event__title">${type} ${destinationById.name}</h3>
              <div class="event__schedule">
                <p class="event__time">
                  <time class="event__start-time" datetime="${dateFrom}">${timeStart}</time>
                  —
                  <time class="event__end-time" datetime="${dateTo}">${timeEnd}</time>
                </p>
                <p class="event__duration">${duration}</p>
              </div>
              <p class="event__price">
                € <span class="event__price-value">${basePrice}</span>
              </p>
              <h4 class="visually-hidden">Offers:</h4>
              <ul class="event__selected-offers">
                ${selectedOffers}
              </ul>
              <button class="event__favorite-btn ${favorite}" type="button">
                <span class="visually-hidden">Add to favorite</span>
                <svg class="event__favorite-icon" width="28" height="28" viewBox="0 0 28 28">
                  <path d="M14 21l-8.22899 4.3262 1.57159-9.1631L.685209 9.67376 9.8855 8.33688 14 0l4.1145 8.33688 9.2003 1.33688-6.6574 6.48934 1.5716 9.1631L14 21z"/>
                </svg>
              </button>
              <button class="event__rollup-btn" type="button">
                <span class="visually-hidden">Open event</span>
              </button>
            </div>
          </li>`;
}

export default class RoutePointView extends AbstractView {
  #point = null;
  #destinations = null;
  #offers = null;
  #handleRollButtonClick = null;
  #handleFavoriteClick = null;

  constructor({ point, destinations, offers, onRollButtonClick, onFavoriteClick }) {
    super();
    this.#point = point;
    this.#destinations = destinations;
    this.#offers = offers;
    this.#handleRollButtonClick = onRollButtonClick;
    this.#handleFavoriteClick = onFavoriteClick;

    if (this.#point) {
      this.element.querySelector('.event__rollup-btn').addEventListener('click', this.#rollButtonClickHandler);
      this.element.querySelector('.event__favorite-btn').addEventListener('click', this.#favoriteClickHandler);
    }
  }

  get template() {
    return createRoutePointTemplate(this.#point, this.#destinations, this.#offers);
  }

  #rollButtonClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleRollButtonClick();
  };

  #favoriteClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleFavoriteClick({ ...this.#point, isFavorite: !this.#point.isFavorite });
  };
}
